/* @lc app=leetcode id=2867 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun countPaths(n: Int, edges: Array<IntArray>): Long = (0..n).map { x -> x >= 2 && (2..Math.sqrt(x.toDouble()).toInt()).none { x % it == 0 } }.let { isp -> IntArray(n + 1) { it }.let { p -> edges.filter { (a, b) -> !isp[a] && !isp[b] }.forEach { (a, b) -> p[find(p, a)] = find(p, b) }.let { (1..n).filter { !isp[it] }.groupingBy { find(p, it) }.eachCount().let { sz -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.filter { (a, b) -> isp[a] && !isp[b] }.groupBy({ it.first }, { sz[find(p, it.second)]!!.toLong() }).values.sumOf { l -> l.fold(0L to 0L) { (tot, acc), s -> (tot + s) to acc + s + tot * s }.second } } } } } }